const text = $input.first().json.content[0].text;
const ideas = JSON.parse(text);
const today = new Date().toISOString().slice(0,10);
return ideas.map(idea => ({ json: { ...idea, datum_erstellt: today, status: 'Entwurf' } }));

const items = $input.all();
const lines = items.map((it, i) => `*${i+1}. ${it.json.pillar} (${it.json.format})*
Hook: ${it.json.hook}
Caption: ${it.json.caption.slice(0,200)}...
Bildidee: ${it.json.bildidee}
`).join('
');
return [{ json: { text: `Neue Post-Entwürfe für @norivagrowbags zur Freigabe:

${lines}

Bitte im Redaktionsplan-Sheet Status auf 'Freigegeben' setzen oder Text anpassen.` } }];
